# =================================================================
# global.R
# Runs FIRST (before ui.R and server.R). Loads all reference data,
# sets up file paths, and holds the two mockup images (splash +
# gender-select screens) embedded as base64 so server.R can show
# them as real <img> elements with no separate image files needed.
# =================================================================

library(shiny)

# ---------------- FILE PATHS (used for reading + writing) ----------------
users_file     <- "users.csv"
wardrobe_file  <- "wardrobe.csv"
history_file   <- "history.csv"

weather_file   <- "weather.csv"
occasion_file  <- "occasion_rules.csv"
locations_file <- "locations.csv"
role_file      <- "role_rules.csv"
student_file   <- "student_rules.csv"

# ---------------- REFERENCE DATA (read-only lookup tables) ----------------
weather_data   <- read.csv(weather_file,   stringsAsFactors = FALSE)
occasion_data  <- read.csv(occasion_file,  stringsAsFactors = FALSE)
locations_data <- read.csv(locations_file, stringsAsFactors = FALSE)
role_data      <- read.csv(role_file,      stringsAsFactors = FALSE)
student_data   <- read.csv(student_file,   stringsAsFactors = FALSE)

# ---------------- USER-GENERATED DATA (read + written back to disk) ------

if (file.exists(users_file)) {
  users_data <- read.csv(users_file, stringsAsFactors = FALSE, colClasses = "character")
} else {
  users_data <- data.frame(
    Username = character(), Password = character(),
    Gender = character(), District = character(), Area = character(),
    CategoryType = character(), RoleOrStudentType = character(),
    stringsAsFactors = FALSE
  )
}

if (file.exists(wardrobe_file)) {
  wardrobe_data <- read.csv(wardrobe_file, stringsAsFactors = FALSE, colClasses = "character")
} else {
  wardrobe_data <- data.frame(
    Username = character(), Category = character(), ItemName = character(),
    Colour = character(), Material = character(),
    stringsAsFactors = FALSE
  )
}

if (file.exists(history_file)) {
  history_data <- read.csv(history_file, stringsAsFactors = FALSE, colClasses = "character")
} else {
  history_data <- data.frame(
    Username = character(), Date = character(), District = character(), Area = character(),
    Occasion = character(), Temperature = character(), Rainfall = character(),
    ClothingType = character(), Colour = character(), Material = character(),
    Footwear = character(), Jewelry = character(),
    stringsAsFactors = FALSE
  )
}

# ---------------- EMBEDDED MOCKUP IMAGES (base64) -------------------------
# splash_img_b64  -> shown on the splash screen (0-5 sec intro)
# gender_img_b64  -> shown at the top of the "Who are you?" gender page
# Used in server.R via tags$img(src = paste0("data:image/jpeg;base64,", ...))

splash_img_b64 <- ""

gender_img_b64 <- ""
